import java.io.IOException;
import java.util.concurrent.TimeUnit;

public class RowHammer {
    public static void rowhammer(long address) throws IOException {
        // Simulate rowhammer by repeatedly accessing the same memory address
        for (int i = 0; i < 1000; i++) {
            Runtime.getRuntime().exec("echo 1 > /proc/sysrq-trigger");
            TimeUnit.MILLISECONDS.sleep(100);
        }
    }

    public static void main(String[] args) throws IOException {
        // Example usage
        rowhammer(0xdeadbeef);
    }
}
```

