const { exec } = require('child_process');

function rowhammer(address) {
    // Simulate rowhammer by repeatedly accessing the same memory address
    for (let i = 0; i < 1000; i++) {
        exec('echo 1 > /proc/sysrq-trigger', (error, stdout, stderr) => {
            if (error) {
                console.error(`exec error: ${error}`);
                return;
            }
            console.log(`stdout: ${stdout}`);
            console.error(`stderr: ${stderr}`);
        });
        setTimeout(() => {}, 100);
    }
}

// Example usage
rowhammer(0xdeadbeef);
